def replace_text(p, text):
    # Retain paragraph style and first run formatting, while removing old field/text runs.
    runs=p.findall('w:r',NS)
    base=max(runs,key=lambda r:len(''.join(r.itertext())),default=None)
    rp=base.find('w:rPr',NS) if base is not None else None
    starts=[copy.deepcopy(c) for c in p if c.tag==W+'bookmarkStart']
    ends=[copy.deepcopy(c) for c in p if c.tag==W+'bookmarkEnd']
    for child in list(p):
        if child.tag != W+'pPr': p.remove(child)
    for c in starts:p.append(c)
    run = E.SubElement(p, W+'r')
    if rp is not None: run.append(copy.deepcopy(rp))
    t = E.SubElement(run, W+'t'); t.set('{http://www.w3.org/XML/1998/namespace}space','preserve'); t.text = text
    for c in ends:p.append(c)

def main():
    if not BACKUP.exists(): shutil.copy2(DOC, BACKUP)
    with ZipFile(BACKUP) as z: parts = {i.filename:z.read(i.filename) for i in z.infolist()}
    root=E.fromstring(parts['word/document.xml']); body=root.find('w:body', NS); originals=list(body)
    changes=[]
    for i,text in R.items():
        p=originals[i]; assert p.tag==W+'p', (i,p.tag)
        old=''.join(p.itertext())
        replace_text(p,text);changes.append({'bodyIndex':i,'replacement':text})
    # Fix the original summary table's looser target to match the methods section.
    table=originals[583]
    if table.tag==W+'tbl':
        cells=table.findall('w:tr',NS)[1].findall('w:tc',NS)
        for c,text in zip(cells,['Real-time analysis','Warm mean <=4.00 s (Section 3.9)','Historical mean 4.05 s; 0.05 s above target','No']):
            ps=c.findall('w:p',NS);replace_text(ps[0],text)
            for p in ps[1:]:c.remove(p)
    # Body heading templates preserve the original thesis heading formatting.
    template=originals[588]
    for text,heading in APPENDIX:
        p=E.Element(W+'p')
        pr=(template if text.startswith('Appendix C:') else originals[589]).find('w:pPr',NS) if heading else originals[590].find('w:pPr',NS)
        if pr is not None:p.append(copy.deepcopy(pr))
        replace_text(p,text)
        if not heading:
            for br in p.findall('.//w:pageBreakBefore',NS):br.getparent().remove(br)
        idx=len(body)-1 if len(body) and body[-1].tag==W+'sectPr' else len(body)
        body.insert(idx,p)
    # Refresh fields on opening; Word owns pagination and TOC page numbers.
    settings=E.fromstring(parts['word/settings.xml'])
    f=settings.find('w:updateFields',NS)
    if f is None:f=E.SubElement(settings,W+'updateFields')
    f.set(W+'val','true')
    parts['word/settings.xml']=E.tostring(settings,xml_declaration=True,encoding='UTF-8',standalone=True)
    # Revised diagrams are produced by build_presentation.py before this script runs.
    for target,name in [('image5.png','architecture.png'),('image7.png','decision-flow.png')]:
        path=OUT/'assets'/name
        if path.exists():
            parts['word/media/'+target]=path.read_bytes()
            from PIL import Image
            im=Image.open(path);cx=int(5.8*914400);cy=int(cx*im.height/im.width)
            p=originals[357 if target=='image5.png' else 396]
            for el in p.iter():
                if el.tag in ['{http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing}extent','{http://schemas.openxmlformats.org/drawingml/2006/main}ext'] and 'cx' in el.attrib:
                    el.set('cx',str(cx));el.set('cy',str(cy))
    parts['word/document.xml']=E.tostring(root,xml_declaration=True,encoding='UTF-8',standalone=True)
    staged=OUT/'thesis-revised.tmp.docx'
    with ZipFile(staged,'w',ZIP_DEFLATED) as z:
        for name,data in parts.items():z.writestr(name,data)
    with ZipFile(staged) as z:
        assert z.testzip() is None
        for name in z.namelist():
            if name.endswith('.xml'):E.fromstring(z.read(name))
    shutil.copy2(staged,DOC);staged.unlink()
    (OUT/'thesis-revision-log.json').write_text(json.dumps({'reviewDate':'2026-10-18','originalSHA256':hashlib.sha256(BACKUP.read_bytes()).hexdigest(),'revisedSHA256':hashlib.sha256(DOC.read_bytes()).hexdigest(),'paragraphRevisions':changes,'appendixParagraphs':len(APPENDIX),'historicalResultsPreserved':True},ensure_ascii=False,indent=2),encoding='utf-8')
    print('Revised thesis:',len(changes),'paragraphs; Appendix C added; original backup preserved.')

if __name__=='__main__':main()
